import React, { useEffect, useState } from "react";
import API from "../api";

export default function StudentDashboard({ user, logout }) {
  const [attendanceRecords, setAttendanceRecords] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [submissions, setSubmissions] = useState([]);
  const [selectedAssignmentId, setSelectedAssignmentId] = useState("");
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    async function fetchData() {
      try {
        const [attendanceRes, assignmentsRes, submissionsRes] = await Promise.all([
          API.get("/attendance/my-attendance"),
          API.get("/assignments"),
          API.get("/submissions/mine")
        ]);
        setAttendanceRecords(attendanceRes.data);
        setAssignments(assignmentsRes.data);
        setSubmissions(submissionsRes.data);
      } catch (err) {
        alert("Failed to load data");
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, []);

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedAssignmentId) return alert("Please select an assignment");
    if (!file) return alert("Please upload a file");

    const formData = new FormData();
    formData.append("assignmentId", selectedAssignmentId);
    formData.append("file", file);

    try {
      setUploading(true);
      await API.post("/submissions", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      alert("Assignment submitted!");

      const submissionsRes = await API.get("/submissions/mine");
      setSubmissions(submissionsRes.data);

      setSelectedAssignmentId("");
      setFile(null);
      e.target.reset();
    } catch (err) {
      alert("Upload failed");
      console.error(err);
    } finally {
      setUploading(false);
    }
  };

  const containerStyle = {
    padding: "30px",
    maxWidth: "900px",
    margin: "auto",
    fontFamily: "Arial, sans-serif",
  };

  const tableStyle = {
    width: "100%",
    borderCollapse: "collapse",
    marginBottom: "30px",
  };

  const thTdStyle = {
    border: "1px solid #ccc",
    padding: "10px",
    textAlign: "left",
  };

  const sectionTitle = {
    marginTop: "40px",
    marginBottom: "10px",
    fontSize: "20px",
    borderBottom: "2px solid #333",
    paddingBottom: "5px",
  };

  return (
    <div style={containerStyle}>
      <h1>📚 Student Dashboard</h1>
      <p>
        Welcome, <strong>{user.username}</strong> (Role: {user.role})
      </p>
      <button onClick={logout} style={{ marginBottom: 20, padding: "8px 16px" }}>
        Logout
      </button>

      <div>
        <h2 style={sectionTitle}>Your Attendance</h2>
        {loading ? (
          <p>Loading attendance...</p>
        ) : (
          <table style={tableStyle}>
            <thead>
              <tr>
                <th style={thTdStyle}>Date</th>
                <th style={thTdStyle}>Status</th>
              </tr>
            </thead>
            <tbody>
              {attendanceRecords.length === 0 ? (
                <tr>
                  <td colSpan="2" style={{ ...thTdStyle, textAlign: "center" }}>
                    No records found.
                  </td>
                </tr>
              ) : (
                attendanceRecords.map((record, i) => (
                  <tr key={i}>
                    <td style={thTdStyle}>{new Date(record.date).toLocaleDateString()}</td>
                    <td style={{ ...thTdStyle, color: record.present ? "green" : "red" }}>
                      {record.present ? "Present" : "Absent"}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        )}
      </div>

      <div>
        <h2 style={sectionTitle}>Assignments</h2>
        {loading ? (
          <p>Loading assignments...</p>
        ) : assignments.length === 0 ? (
          <p>No assignments available</p>
        ) : (
          <table style={tableStyle}>
            <thead>
              <tr>
                <th style={thTdStyle}>Title</th>
                <th style={thTdStyle}>Description</th>
                <th style={thTdStyle}>Due Date</th>
              </tr>
            </thead>
            <tbody>
              {assignments.map((a) => (
                <tr key={a._id}>
                  <td style={thTdStyle}>{a.title}</td>
                  <td style={thTdStyle}>{a.content || "—"}</td>
                  <td style={thTdStyle}>{new Date(a.dueDate).toLocaleDateString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div>
        <h2 style={sectionTitle}>Submit Assignment</h2>
        <form onSubmit={handleSubmit} style={{ marginBottom: 30 }}>
          <label>
            Assignment:
            <select
              required
              value={selectedAssignmentId}
              onChange={(e) => setSelectedAssignmentId(e.target.value)}
              style={{ marginLeft: 10, marginBottom: 10, padding: 5 }}
            >
              <option value="">-- Select --</option>
              {assignments.map((a) => (
                <option key={a._id} value={a._id}>
                  {a.title}
                </option>
              ))}
            </select>
          </label>
          <br />
          <input
            type="file"
            accept=".pdf,.doc,.docx"
            onChange={handleFileChange}
            required
            style={{ marginBottom: 10 }}
          />
          <br />
          <button type="submit" disabled={uploading} style={{ padding: "8px 16px" }}>
            {uploading ? "Uploading..." : "Submit Assignment"}
          </button>
        </form>
      </div>

      <div>
        <h2 style={sectionTitle}>Your Submissions</h2>
        {loading ? (
          <p>Loading submissions...</p>
        ) : submissions.length === 0 ? (
          <p>No submissions found.</p>
        ) : (
          <table style={tableStyle}>
            <thead>
              <tr>
                <th style={thTdStyle}>Assignment</th>
                <th style={thTdStyle}>Submitted On</th>
                <th style={thTdStyle}>File</th>
                <th style={thTdStyle}>Grade</th>
              </tr>
            </thead>
            <tbody>
              {submissions.map((sub) => (
                <tr key={sub._id}>
                  <td style={thTdStyle}>{sub.assignment.title}</td>
                  <td style={thTdStyle}>{new Date(sub.submittedAt).toLocaleDateString()}</td>
                  <td style={thTdStyle}>
                    <a
                      href={`http://localhost:5000/${sub.file}`}
                      target="_blank"
                      rel="noreferrer"
                    >
                      Download
                    </a>
                  </td>
                  <td style={thTdStyle}>{sub.grade != null ? sub.grade : "Not graded yet"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
